/// Turns a title into a URL slug
///
/// Words are lowercased and joined with `-`. Any run of non-alphanumeric
/// characters acts as a separator. Non-ASCII letters are kept.
///
/// # Arguments
///
/// * `title` - The title to slugify
///
/// # Examples
///
/// ```
/// assert_eq!(textkit::slugify("Hello, World!"), "hello-world");
/// ```
pub fn slugify(title: &str) -> String {
    // split the title into words on anything that is not a letter or digit
    title
        .split(|c: char| !c.is_alphanumeric())
        // drop the empty pieces left by repeated or leading/trailing separators
        .filter(|word| !word.is_empty())
        // lowercase each word
        .map(str::to_lowercase)
        .collect::<Vec<String>>()
        // join the words with dashes
        .join("-")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn slugify_basic_title() {
        assert_eq!(slugify("Hello World"), "hello-world");
    }

    #[test]
    fn slugify_collapses_punctuation_and_whitespace() {
        assert_eq!(slugify("  Hello,   World!! "), "hello-world");
    }

    #[test]
    fn slugify_keeps_non_ascii() {
        assert_eq!(slugify("Café Münster"), "café-münster");
    }

    #[test]
    fn slugify_empty() {
        assert_eq!(slugify(""), "");
    }
